questions.solution:
function updateTask(tasks, id, patch) {
  return tasks.map((task) => (task.id === id ? { ...task, ...patch } : task));
}

function renameCustomer(appt, name) {
  return { ...appt, customer: { ...appt.customer, name } };
}
